"""Read the completed frozen run; save a transparent, unweighted deployment recommendation."""
import datetime,hashlib,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
SOURCE=ROOT/'reports/evaluation/unified_rag_v6_evaluation_20261121_164940'

def read(n):return json.loads((SOURCE/n).read_text(encoding='utf-8'))
def sha(p):return hashlib.file_digest(p.open('rb'),'sha256').hexdigest()

def main():
    original=read('evaluation_metrics_11.json');qc=read('evaluation_metrics_11_source_qc.json');paired=read('paired_sample_comparison.json');identity=read('model_runtime_identity.json');audit=read('final_result_quality_audit.json');validation=read('workbook_validation.json');state=read('finalization_status.json')
    assert state['status']=='COMPLETE' and state['stage']=='ALL_COMPLETE';assert audit['protected']['unchanged']==636 and validation['cached_formula_values_match_json']
    manifest=read('result_artifact_manifest.json');expected={pathlib.Path(x['path']).name:x['sha256'] for x in manifest['files']}
    inputs=['evaluation_metrics_11.json','evaluation_metrics_11_source_qc.json','paired_sample_comparison.json','model_runtime_identity.json','final_result_quality_audit.json','workbook_validation.json']
    checks=[{'path':str(SOURCE/n),'sha256':sha(SOURCE/n),'matches_result_manifest':sha(SOURCE/n)==expected[n]} for n in inputs];assert all(x['matches_result_manifest'] for x in checks)
    now=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8)));out=ROOT/'reports/evaluation'/('unified_rag_v6_model_recommendation_'+now.strftime('%Y%m%d_%H%M%S'));out.mkdir()
    models={}
    for m,v in qc['models'].items():
        a=v['layers']['model'];perf=v['timing_memory'];models[m]={'tag':identity[m]['tag'],'digest':identity[m]['digest'],'source_50_content':a['source_50_content_correct_rate'],'source_50_program_gate':a['source_50_task_success'],'logical_fixed_37_content':a['logical_accuracy']['fixed_content_success'],'arithmetic_fixed_13_content':a['arithmetic_accuracy']['fixed_content_success'],'logical_conditional':{'accuracy':a['logical_accuracy']['conditional_accuracy'],'n':a['logical_accuracy']['conditional_n']},'arithmetic_conditional':{'accuracy':a['arithmetic_accuracy']['conditional_accuracy'],'n':a['arithmetic_accuracy']['conditional_n']},'raw_json':v['raw_schema'],'accepted_model_partial_answers':v['model_validated_answer_rate'],'performance':perf,'paired_quality':{k:{'mean':paired[k]['models'][m]['mean'],'n':paired[k]['common_n']} for k in ('model_faithfulness','model_judge_relevance','model_bge_cosine')}}
    p2=models['M2']['performance'];p4=models['M4']['performance'];comparison={'m4_over_m2_mean_api_wall_ratio':p4['wall_seconds']['mean']/p2['wall_seconds']['mean'],'m4_minus_m2_source50_correct':models['M4']['source_50_content']['success_n']-models['M2']['source_50_content']['success_n'],'m4_minus_m2_sampled_vram_gib':p4['peak_dedicated_vram_gib']['mean']-p2['peak_dedicated_vram_gib']['mean'],'same_180_questions':True,'wall_ratio_includes_observed_answer_length_and_abstention_mix':True}
    decision={'created_at':now.isoformat(),'source_run':SOURCE.name,'primary_research_deployment_recommendation':'M2','quality_first_alternative':'M4','logical_subset_leader':'M3','paired_judge_quality_leader':'M1','assumed_use_case':'Interactive research website on current RTX 4060 8 GB host; source and citation gates retained','decision_method':'Explicit task tradeoff; no weighted score or significance claim','decision_priorities':['Interactive latency and output stability on existing hardware','Confirmed source-content task success on fixed denominator','Memory headroom and observable failure modes'],'not_claimed':['M2 has highest professional accuracy','Any model is expert validated','A universally best model or formal benchmark Winner','System sampled RAM/VRAM are model-process-only footprint'],'models':models,'shared_p5':original['shared_context_precision'],'comparison':comparison,'limitations':{'human_gold':0,'source_reference_questions':50,'source_groups':10,'reference_files':3,'common_judge_questions':35,'common_bge_questions':37,'common_arithmetic_questions':paired['model_arithmetic']['common_n'],'source_qa_scope':qc['post_run_source_qc'],'remaining_extra_claim_cases_need_review':2,'no_production_switch':True},'input_integrity':checks}
    (out/'model_recommendation_evidence.json').write_text(json.dumps(decision,ensure_ascii=False,indent=2),encoding='utf-8')
    lines=['# 四模型評測整理與部署建議',f'來源：{SOURCE.name}。720次新生成，每模型180題；本次僅整理既有結果，沒有新推論或Corpus修改。','', '**建議目前互動式研究網站以M2（Qwen2.5-Coder-7B-Instruct）作主要部署模型。M4（Gemma2-9B-It）是本輪來源內容符合率領先的品質優先備選。**','', '此建議以目前RTX 4060 8 GB主機、互動延遲、格式穩定與來源回答表現為條件，沒有建立任意加權總分，也不是宣稱M2專業準確率最高。','', '| 固定分母與部署指標 | M1 | M2 | M3 | M4 |','|---|---:|---:|---:|---:|']
    for title,key in [('50題來源內容符合','source_50_content'),('37題Logical內容成功','logical_fixed_37_content'),('13題Arithmetic內容成功','arithmetic_fixed_13_content'),('50題內容＋現有程式閘','source_50_program_gate')]:
        lines.append('| '+title+' | '+' | '.join(f'{models[m][key]["success_n"]}/{models[m][key]["n"]} ({models[m][key]["rate"]:.2%})' for m in models)+' |')
    lines.append('| 原始JSON符合率（各N=180） | '+' | '.join(f'{models[m]["raw_json"]["rate"]:.2%}' for m in models)+' |')
    for title,key in [('首個可見內容TTFT（秒）','ttft_seconds'),('平均生成API耗時（秒）','wall_seconds'),('TPS（tokens/s）','tps'),('系統RAM採樣峰值平均（GiB）','peak_system_ram_gib'),('設備VRAM採樣峰值平均（GiB）','peak_dedicated_vram_gib')]:lines.append('| '+title+' | '+' | '.join(f'{models[m]["performance"][key]["mean"]:.2f} (N={models[m]["performance"][key]["n"]})' for m in models)+' |')
    lines+=['', '| 共同有效題目品質比較 | M1 | M2 | M3 | M4 |','|---|---:|---:|---:|---:|']
    for title,key in [('Faithfulness，配對N=35','model_faithfulness'),('Judge Answer Relevance，配對N=35','model_judge_relevance'),('BGE-M3 Cosine，配對N=37','model_bge_cosine')]:lines.append('| '+title+' | '+' | '.join(f'{models[m]["paired_quality"][key]["mean"]:.4f}' for m in models)+' |')
    lines+=['', '以上已涵蓋原11項指標：Faithfulness、Judge Relevance、BGE Cosine、Structured IFR、TTFT、TPS、RAM、VRAM、P@5、Logical、Arithmetic。Logical／Arithmetic主比較使用相同固定題組的內容成功率；各模型不同有效N的條件式準確率另保留於原Excel與證據JSON。', '', '共用Context Precision@5為0.35，有效12題／60段AI來源審查，不能外推全部180題，也不形成四組不同模型檢索成績。', '', '## 選型判斷', '', f'- M2：原始JSON符合率99.44%，平均TTFT {p2["ttft_seconds"]["mean"]:.2f}秒、生成API耗時{p2["wall_seconds"]["mean"]:.2f}秒；與M4同為80/180筆模型回答通過現有程式閘。固定50題內容19/50，低於M4，但互動延遲與目前硬體負擔較合適。', f'- M4：固定50題內容24/50最高，Arithmetic固定題組9/13最高，JSON符合率100%。平均API耗時{p4["wall_seconds"]["mean"]:.2f}秒，是M2約{comparison["m4_over_m2_mean_api_wall_ratio"]:.1f}倍；設備VRAM採樣峰值平均較M2高{comparison["m4_minus_m2_sampled_vram_gib"]:.2f} GiB。適合作品質優先的備選，但不能把48%來源內容符合率稱為高可靠專家系統。', '- M3：Logical固定題組17/37領先，但Arithmetic僅1/13，並有多筆題目複誦／未作答內容警示；不能只因50題程式閘通過率30%最高就選為整體最佳。', '- M1：共同題目中的Judge Faithfulness／Relevance最高，但JSON符合率92.22%、平均可見TTFT7.67秒，通過程式閘的模型回答僅41/180；高Judge均值不能取代回答涵蓋與固定分母成功率。', '', '## 判讀限制', '', '- Human Gold為0；50題來源子集僅依賴10個來源群組、3份原件。原180題已用於系統調整，屬探索性回歸，不是未曝光Holdout。', '- 使用另存的來源QA修正版；原始AI分數與原始回答均保留。仍有2件額外因果／適用性主張待查，其他AI判定未全數獲獨立專家核實。', '- 固定分母的未成功包含拒答、不完整、無法判定或驗證失敗，不能全部解讀為專業答案錯誤。共同有效Arithmetic僅1題，不能據此宣稱模型算術能力排名。', '- 有30筆內容符合判準卻被現有程式閘拒絕，其中17筆為算術。過閘率受數值／單位／引用檢查影響，不能直接當作模型專業正確率。', '- TTFT與API耗時不含預先凍結的檢索階段；TPS使用各模型自身tokenizer。平均耗時比亦反映回答長度與拒答分布，並非等長文字的純速度倍數。', '- RAM與VRAM是系統／設備層級採樣峰值的平均，不是模型程序專屬用量；不據此自行建立Memory Pressure分數。', '', '## 執行範圍', '', '本次提供部署建議，不切換Production、不更改模型預設、不修改Corpus、SQLite或歷史評測。所有比較數值由已保存JSON重算，輸入檔雜湊與既有成果Manifest一致。', '', '## 模型身分', '']
    for m in models:lines.append(f'- {m}：`{models[m]["tag"]}`；digest `{models[m]["digest"]}`。')
    (out/'model_recommendation_report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print(json.dumps({'directory':str(out),'recommended_primary':'M2','quality_leader':'M4','source_hashes_verified':True,'mean_api_wall_ratio_M4_over_M2':comparison['m4_over_m2_mean_api_wall_ratio']},ensure_ascii=False))

if __name__=='__main__':main()
